<?php
$root=dirname(__DIR__);$cfgFile=$root.'/config.php';$cfg=file_exists($cfgFile)?require $cfgFile:require $root.'/config.example.php';$db=$cfg['db'];$msg='';
try{$pdo=new PDO("mysql:host={$db['host']};dbname={$db['name']};charset=utf8mb4",$db['user'],$db['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec("CREATE TABLE IF NOT EXISTS enquiries(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(80),trip VARCHAR(190),message TEXT,created_at DATETIME NOT NULL);CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL);CREATE TABLE IF NOT EXISTS pages(id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(190) UNIQUE NOT NULL,title VARCHAR(190) NOT NULL,body MEDIUMTEXT,status ENUM('draft','published') DEFAULT 'draft',meta_title VARCHAR(190),meta_description VARCHAR(255),updated_at DATETIME NOT NULL);CREATE TABLE IF NOT EXISTS redirects(id INT AUTO_INCREMENT PRIMARY KEY,old_path VARCHAR(255) UNIQUE NOT NULL,new_path VARCHAR(255) NOT NULL,status_code SMALLINT DEFAULT 301,created_at DATETIME NOT NULL);");if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pass)>=10){$st=$pdo->prepare('INSERT INTO admins(email,password_hash,created_at) VALUES(?,?,NOW())');$st->execute([$email,password_hash($pass,PASSWORD_DEFAULT)]);$msg='Admin created. Delete or rename this setup file now.';}else{$msg='Use a valid email and a password of at least 10 characters.';}}}catch(Throwable $e){$msg='Database connection failed. Check config.php and database settings.';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>TWE Setup</title></head><body><main class="section wrap narrow"><h1>Tanzania Wildlife Epic Setup</h1><p><?=$msg?></p><form class="contact-form" method="post"><input type="email" name="email" placeholder="Admin email" required><input type="password" name="password" placeholder="Admin password (10+ characters)" required><button class="btn gold">Create Admin</button></form></main></body></html>
